cd /private/var/folders/9t/wb1rb8796x9dx_7n376r8x300000gq/T/miri-field/r1/03-tracker-extension/rust/claude-opus/2; cat > src/main.rs <<'EOF'
//! A small task tracker.

use std::env;
use std::fs;

struct Task {
    id: i64,
    title: String,
    done: bool,
    priority: u8,
}

const DEFAULT_PRIORITY: u8 = 5;

fn find(tasks: &mut [Task], id: i64) -> Option<&mut Task> {
    tasks.iter_mut().find(|task| task.id == id)
}

/// Parses a priority: exactly one digit from 0 to 9.
fn parse_priority(text: &str) -> Option<u8> {
    match text.as_bytes() {
        [digit @ b'0'..=b'9'] => Some(digit - b'0'),
        _ => None,
    }
}

/// The tasks in list order: priority ascending, then id ascending.
fn ordered(tasks: &[Task]) -> Vec<&Task> {
    let mut sorted: Vec<&Task> = tasks.iter().collect();
    sorted.sort_by_key(|task| (task.priority, task.id));
    sorted
}

fn main() {
    let path = env::args().nth(1).expect("a command file");
    let text = fs::read_to_string(&path).expect("a readable command file");
    let mut tasks: Vec<Task> = Vec::new();
    let mut next_id = 1;

    for line in text.trim_end_matches('\n').split('\n') {
        if line.trim().is_empty() {
            continue;
        }
        let (command, rest) = match line.split_once(' ') {
            Some((command, rest)) => (command, rest),
            None => (line, ""),
        };

        if command == "add" {
            tasks.push(Task {
                id: next_id,
                title: rest.to_string(),
                done: false,
                priority: DEFAULT_PRIORITY,
            });
            println!("added {}", next_id);
            next_id += 1;
        } else if command == "done" {
            let id: i64 = rest.parse().expect("a task id");
            match find(&mut tasks, id) {
                None => println!("no such task {}", id),
                Some(task) => {
                    task.done = true;
                    println!("done {}", id);
                }
            }
        } else if command == "prio" {
            let (id_text, p_text) = match rest.split_once(' ') {
                Some((id_text, p_text)) => (id_text, p_text),
                None => (rest, ""),
            };
            let id: i64 = id_text.parse().expect("a task id");
            match find(&mut tasks, id) {
                None => println!("no such task {}", id),
                Some(task) => match parse_priority(p_text) {
                    None => println!("bad priority {}", p_text),
                    Some(priority) => {
                        task.priority = priority;
                        println!("prio {} {}", id, p_text);
                    }
                },
            }
        } else if command == "list" {
            if rest == "all" {
                for task in ordered(&tasks) {
                    let mark = if task.done { 'x' } else { '-' };
                    println!("{} {} {}", mark, task.id, task.title);
                }
            } else {
                for task in ordered(&tasks).into_iter().filter(|task| !task.done) {
                    println!("{} {}", task.id, task.title);
                }
            }
        } else {
            let word = line.split_whitespace().next().unwrap_or(command);
            println!("? {}", word);
        }
    }
}
